import{_ as a,o,c as t,a2 as s}from"./chunks/framework.9ngYh_O2.js";const g=JSON.parse('{"title":"Docker 构建排错","description":"","frontmatter":{},"headers":[],"relativePath":"debugging/docker-build.md","filePath":"debugging/docker-build.md","lastUpdated":1788501998000}'),d={name:"debugging/docker-build.md"};function r(n,e,i,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="docker-构建排错" tabindex="-1">Docker 构建排错 <a class="header-anchor" href="#docker-构建排错" aria-label="Permalink to &quot;Docker 构建排错&quot;">​</a></h1><p>这里只记录已经真实出现的问题，不提前编造解决方案。</p><h2 id="_1-legacy-builder-不支持-progress" tabindex="-1">1. legacy builder 不支持 <code>--progress</code> <a class="header-anchor" href="#_1-legacy-builder-不支持-progress" aria-label="Permalink to &quot;1. legacy builder 不支持 `--progress`&quot;">​</a></h2><p><strong>现象</strong></p><p>【运行验证】第一次尝试向 legacy builder 传入 <code>--progress</code>，参数在真正构建前被拒绝，没有生成镜像。</p><p><strong>原因与处理</strong></p><p>【运行验证】失败发生在 Docker 命令参数层，与 ROS、APT 和 EGO 源码无关。</p><p>【源码确认】当前 <code>build-image.sh</code> 已移除该参数，只执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local/ego-planner-humble:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>【运行验证】第二次尝试已进入基础镜像拉取，说明这个参数阻塞点已越过，但并不表示镜像构建完成。</p><h2 id="_2-docker-hub-ipv6-连接超时" tabindex="-1">2. Docker Hub IPv6 连接超时 <a class="header-anchor" href="#_2-docker-hub-ipv6-连接超时" aria-label="Permalink to &quot;2. Docker Hub IPv6 连接超时&quot;">​</a></h2><p><strong>现象</strong></p><p>【运行验证】第二次构建在拉取 <code>ros:humble-ros-base-jammy</code> 时，通过 IPv6 连接 Docker Hub 超时；本地仍无镜像。</p><p><strong>原因边界</strong></p><p>【运行验证】失败点是 Docker Hub 的 IPv6 网络连接。</p><p>【待验证】还不能确定是临时波动、IPv6 路由、Docker daemon 网络设置、DNS 返回顺序还是代理链路。没有证据支持修改 ROS 或 Ubuntu APT 源。</p><p><strong>结果</strong></p><p>【运行验证】配置好代理后重跑 <code>./build-image.sh</code>，基础镜像拉取成功，镜像最终构建完成（<code>local/ego-planner-humble:latest</code>，4.84 GB）。<strong>这个阻塞点已经解决。</strong></p><div class="tip custom-block"><p class="custom-block-title">通用经验</p><p>镜像拉取失败时，<strong>先分清是&quot;网络到不了&quot;还是&quot;配置写错了&quot;</strong>。看报错里的关键词：出现 <code>timeout</code>、<code>connection refused</code>、<code>i/o timeout</code> 基本都是网络；出现 <code>unknown flag</code>、<code>invalid reference format</code> 才是命令写错了。这两类的处理方式完全不同，混在一起排查会很浪费时间。</p></div><h2 id="_3-编译期的三个坑" tabindex="-1">3. 编译期的三个坑 <a class="header-anchor" href="#_3-编译期的三个坑" aria-label="Permalink to &quot;3. 编译期的三个坑&quot;">​</a></h2><p>镜像好了之后，<code>colcon build</code> 阶段还有三个问题，因为它们和编译流程绑得很紧，<strong>完整记录写在 <a href="/drone-learning-lab/ego-planner/build">第二步：编译工作空间</a></strong>，这里只列索引：</p><table tabindex="0"><thead><tr><th>问题</th><th>一句话原因</th><th>详见</th></tr></thead><tbody><tr><td><code>AMENT_TRACE_SETUP_FILES: unbound variable</code></td><td><code>set -u</code> 开在 <code>source</code> ROS 之前</td><td><a href="/drone-learning-lab/ego-planner/build">第二步 3.1</a></td></tr><tr><td><code>Cannot locate rosdep definition for [Eigen3]</code> 等 18 条</td><td>上游 <code>package.xml</code> 用了大写的 CMake 包名，rosdep 只认小写 key</td><td><a href="/drone-learning-lab/ego-planner/build">第二步 3.3</a></td></tr><tr><td>找不到 <code>pcl_ros</code></td><td>镜像里漏装，已补进 Dockerfile 第二个 <code>RUN</code> 层</td><td><a href="/drone-learning-lab/getting-started/environment">第一步 4</a></td></tr></tbody></table><h2 id="判断边界" tabindex="-1">判断边界 <a class="header-anchor" href="#判断边界" aria-label="Permalink to &quot;判断边界&quot;">​</a></h2><p>这条链子上每一环都要单独验证，<strong>前一环成功不能推断后一环成功</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>命令参数正确 → 镜像拉取成功 → 镜像构建完成</span></span>\n<span class="line"><span>→ rosdep 依赖解决 → colcon 20 包编译成功</span></span>\n<span class="line"><span>→ 节点能启动 → 话题在流动 → 规划结果正确</span></span></code></pre></div><p>【运行验证】截至目前这条链子已经<strong>全部走通</strong>。运行阶段的问题记录在 <a href="/drone-learning-lab/debugging/ego-runtime">运行期问题</a>。</p>',26)])])}const u=a(d,[["render",r]]);export{g as __pageData,u as default};
